<?php
require_once __DIR__.'/lesson_book_excel.php';
/** Dynamic application download, built with CDS's existing OOXML writer. */
function gdp_excel_template_sheet(array $headers,array $rows,array $widths,bool $data=false): string {
    $last=max(2,count($rows)+1);$cols='';foreach($widths as$i=>$width)$cols.='<col min="'.($i+1).'" max="'.($i+1).'" width="'.$width.'" customWidth="1"/>';
    $xml='<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetViews><sheetView workbookViewId="0" showGridLines="0"><pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews><sheetFormatPr defaultRowHeight="28"/><cols>'.$cols.'</cols><sheetData><row r="1" ht="32" customHeight="1">';
    foreach($headers as$i=>$h)$xml.=lb_xlsx_text(lb_xlsx_col($i+1).'1',$h,2);$xml.='</row>';
    foreach($rows as$i=>$row){$n=$i+2;$xml.='<row r="'.$n.'" ht="32" customHeight="1">';foreach($row as$j=>$value){$ref=lb_xlsx_col($j+1).$n;$xml.=is_int($value)?lb_xlsx_number($ref,$value,4):lb_xlsx_text($ref,$value,$j===0?7:3);}$xml.='</row>';}
    $xml.='</sheetData><autoFilter ref="A1:'.lb_xlsx_col(count($headers)).$last.'"/>';
    if($data)$xml.='<dataValidations count="2"><dataValidation type="whole" operator="between" allowBlank="1" showErrorMessage="1" errorTitle="Tiết chương trình" error="Nhập số nguyên từ 1 đến 35" sqref="D2:E5001"><formula1>1</formula1><formula2>35</formula2></dataValidation><dataValidation type="list" allowBlank="1" showErrorMessage="1" errorTitle="Mã giáo viên" error="Chọn mã trong trang Giao vien" sqref="A2:A5001"><formula1>MaGiaoVien</formula1></dataValidation></dataValidations>';
    return $xml.'<pageMargins left="0.3" right="0.3" top="0.4" bottom="0.4" header="0.2" footer="0.2"/><pageSetup orientation="landscape" fitToWidth="1" fitToHeight="0"/></worksheet>';
}
function gdp_excel_template(array $context,array $configs,string $versionName,string $target): bool {
    $teachers=[];$byTeacher=[];
    foreach($context['catalog']as$matches)foreach($matches as$r){$valid=count($matches)===1&&$r['teacher']!=='';$teachers[]=[$r['code'],$r['name'],$valid?'Có thể nhập':'Kiểm tra mã / tên trong CSDL và phân công'];if($valid)$byTeacher[$r['teacher']][]=$r['code'];}
    $rows=[];foreach($context['classes']as$class){if(isset($configs[$class]))foreach($configs[$class]['ranges']as$r)$rows[]=[count($byTeacher[$r['teacher']]??[])===1?$byTeacher[$r['teacher']][0]:'',$r['teacher'],$class,(int)$r['from'],(int)$r['to']];else$rows[]=['','',$class,1,35];}
    if(!$rows)$rows[]=['','','',1,35];if(!$teachers)$teachers[]=['','','Cần khai mã trong CSDL và đồng bộ giáo viên vào phân công.'];
    $instructions=[['Phiên bản',$versionName],['Nhập dữ liệu','Chỉ sửa trang Phan cong GDDP. Mỗi dòng là một giáo viên, một lớp, một dải tiết.'],['Mã giáo viên','Sao chép từ trang Giao vien. Cột Mã giáo viên là văn bản, giữ số 0 đầu.'],['Họ tên','Được để trống; nếu điền phải khớp mã trong CSDL. Không ghép theo tên gần giống.'],['Dải tiết','Số nguyên 1–35. Mỗi lớp đủ 35 tiết và không trùng; đây là tiết chương trình, không phải tuần.'],['Chia dải','Ví dụ cùng một lớp: GV A tiết 1–10, GV B tiết 11–25, GV C tiết 26–35.'],['Phạm vi','Thêm dòng để chia dải; xóa dòng của lớp không muốn cập nhật. Nhập lại sẽ thay toàn bộ dải của lớp trong file.'],['Xác nhận','Tải file lên, kiểm tra lỗi và xem trước, rồi xác nhận. Không dùng công thức.'],['Công bố','Khóa và công bố phân công để TKB lấy bản mới. TKB đã công bố và sổ đã ký giữ nguyên.']];
    $sheets=[['Phan cong GDDP',['Mã giáo viên','Họ tên','Lớp','Từ tiết','Đến tiết'],$rows,[21,35,12,14,14]],['Giao vien',['Mã giáo viên','Họ tên','Đối chiếu'],$teachers,[21,35,60]],['Huong dan',['Mục','Hướng dẫn'],$instructions,[22,110]]];
    $styles=str_replace('<cellXfs count="7">','<cellXfs count="8">',lb_xlsx_styles());$styles=str_replace('</cellXfs>','<xf numFmtId="49" fontId="0" fillId="0" borderId="1" xfId="0" applyNumberFormat="1" applyAlignment="1"><alignment vertical="center" wrapText="1"/></xf></cellXfs>',$styles);
    $files=lb_xlsx_base_files('Phân công GDĐP 1–35','Phan cong GDDP','',$styles);$ws='';$rels='';$types='';$names='';
    foreach($sheets as$i=>[$name,$headers,$data,$widths]){$id=$i+1;$ws.='<sheet name="'.lb_xlsx_xml($name).'" sheetId="'.$id.'" r:id="rId'.$id.'"/>';$rels.='<Relationship Id="rId'.$id.'" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet'.$id.'.xml"/>';$types.='<Override PartName="/xl/worksheets/sheet'.$id.'.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>';$files['xl/worksheets/sheet'.$id.'.xml']=gdp_excel_template_sheet($headers,$data,$widths,$i===0);$names.='<vt:lpstr>'.lb_xlsx_xml($name).'</vt:lpstr>';}
    $files['xl/workbook.xml']='<?xml version="1.0" encoding="UTF-8" standalone="yes"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><bookViews><workbookView/></bookViews><sheets>'.$ws.'</sheets><definedNames><definedName name="MaGiaoVien">\'Giao vien\'!$A$2:$A$'.(count($teachers)+1).'</definedName></definedNames></workbook>';
    $files['xl/_rels/workbook.xml.rels']='<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'.$rels.'<Relationship Id="rId4" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>';
    $files['[Content_Types].xml']=preg_replace('~<Override PartName="/xl/worksheets/sheet1.xml"[^>]*/>~',$types,$files['[Content_Types].xml']);
    $files['docProps/app.xml']='<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Properties xmlns="http://schemas.openxmlformats.org/officeDocument/2006/extended-properties" xmlns:vt="http://schemas.openxmlformats.org/officeDocument/2006/docPropsVTypes"><Application>CDS</Application><TitlesOfParts><vt:vector size="3" baseType="lpstr">'.$names.'</vt:vector></TitlesOfParts></Properties>';
    return lb_xlsx_zip($files,$target);
}
